package com.sobrenaturaldirector.spatial.validation;
import java.util.*;import com.sobrenaturaldirector.spatial.geometry.*;import com.sobrenaturaldirector.spatial.model.*;
public final class SpatialPlanValidator {private SpatialPlanValidator(){}public static List<String> validate(AbstractSpatialPlan p){List<String>e=new ArrayList<String>();if(p==null)return Collections.singletonList("plan missing");Map<String,SpatialNodePlacement>nodes=new HashMap<String,SpatialNodePlacement>();Map<String,String>sources=new HashMap<String,String>();for(SpatialNodePlacement n:p.getNodes()){if(nodes.put(n.getPlacementId(),n)!=null)e.add("duplicate placement "+n.getPlacementId());if(sources.put(n.getSourceNodeId(),n.getPlacementId())!=null)e.add("duplicate source placement "+n.getSourceNodeId());if(n.getVolume().volume()>p.getBudget().getMaxVolume())e.add("node volume exceeds budget "+n.getPlacementId());}for(int i=0;i<p.getNodes().size();i++)for(int j=i+1;j<p.getNodes().size();j++)if(p.getNodes().get(i).isMandatory()&&p.getNodes().get(j).isMandatory()&&p.getNodes().get(i).getVolume().overlaps(p.getNodes().get(j).getVolume()))e.add("illegal mandatory overlap");for(SpatialConnectorPlacement c:p.getConnectors()){if(!nodes.containsKey(c.getFromPlacementId())||!nodes.containsKey(c.getToPlacementId()))e.add("connector placement endpoint missing "+c.getPlacementId());else if(!c.getVolume().overlaps(nodes.get(c.getFromPlacementId()).getVolume())||!c.getVolume().overlaps(nodes.get(c.getToPlacementId()).getVolume()))e.add("connector does not touch endpoints "+c.getPlacementId());}for(LocalAnchor a:p.getAnchors().values()){SpatialNodePlacement n=nodes.get(a.getPlacementId());if(n==null)e.add("anchor placement missing "+a.getId());else if(!n.getVolume().contains(a.getPosition()))e.add("anchor outside placement "+a.getId());}LocalAabb f=p.getFootprint().getBounds();for(SpatialNodePlacement n:p.getNodes())if(!f.contains(n.getVolume()))e.add("node outside footprint "+n.getPlacementId());return e;}}
